    peer: (j.config && j.config.peers && j.config.peers[0] && j.config.peers[0].public_key) || WARP_PEER_PUB, /* ⚡ ۲۴۴: کلید Peer از پاسخ واقعی API — ثابت فقط پشتیبان */
