  for (const u of s.users) { if (typeof u.frag !== "string") u.frag = ""; u.alerted80 = !!u.alerted80; u.alertedExp = !!u.alertedExp; }
  s.settings = Object.assign(defaultSettings(), s.settings || {});
  /* ⚡ 2.5.0-نهایی: nodes مسموم (restore دست‌ساز: [null,5,"junk"]) قبلاً کل پنل را آجر می‌کرد —
     حتی /api/state می‌مرد (اثبات پروب: n.cc روی null). فیلتر در گلوگاه = همه‌ی مسیرهای بارگذاری تمیز. */
  s.settings.nodes = Array.isArray(s.settings.nodes)
    ? s.settings.nodes.filter((n) => n && typeof n === "object" && typeof n.ip === "string" && n.ip)
        .map((n) => Object.assign({}, n, { ip: String(n.ip).slice(0, 64), port: Number(n.port) || 443, bad: Number(n.bad) || 0 }))
    : [];
  /* ⚡ 2.6.1 (۲۴۹ — ریشه‌ی «بعد از بستن/باز کردن پنل همه در صف بررسی‌اند»): خود-شفای گلوگاه —
     نودِ checked دیگر هیچ‌وقت کاندید نیست (پرچم‌های _fresh/unkِ چسبیده پاک)؛ صفِ تأیید سقفِ
     ۱۰تایی دارد (تازه‌ترین‌ها می‌مانند) — کاندیدهای بی‌حکمِ انباشته دیگر کل لیست را نمی‌گیرند. */
  s.settings.nodes = s.settings.nodes.map((n) => {
    if (n.checked) { if (n._fresh) { const c = Object.assign({}, n); delete c._fresh; n = c; } if (n.unk) { const c = Object.assign({}, n); delete c.unk; n = c; } }
    return n;
  });
  const pend249 = s.settings.nodes.filter((n) => !n.checked);
  if (pend249.length > 10) {
    const keep249 = new Set(pend249.sort((a, b) => (b.created || 0) - (a.created || 0)).slice(0, 10)); /* ⚡ ۲۴۹g: فقط مُهر created — ms پینگ است نه سن! */
    s.settings.nodes = s.settings.nodes.filter((n) => n.checked || keep249.has(n));
  }
