  if (sub === "/api/proxy-check" && request.method === "POST") {
    const res = await checkProxies(state, 5); /* ⚡ ۲۵۹: خواست کاربر — دکمه «بررسی ProxyIPها» ۵ منبع در هر کلیک (بودجه زیردرخواست نصف شد) */
    if (!(await saveState(env, state))) return json({ ok: false, error: "ذخیره‌سازی موقتاً ممکن نشد — تغییر اعمال نشد؛ چند لحظه بعد دوباره تلاش کنید." }, 503);
    return json({ ok: true, at: res.at, alive: res.alive, total: res.total, removed: res.removed, vf: res.vf || 0, proxyIPs: state.settings.proxyIPs });
  }

