function userLimit(u) { const n = Math.floor(Number(u && u.limit)); return isFinite(n) && n > 0 ? Math.min(100, n) : 0; }
// ⚡ 2.2.8: هر IP سالم کلادفلر روی همه‌ی پورت‌های TLS استاندارد هم گوش می‌دهد — وقتی
