  // ⚡ 2.3.7: اولویت واقعیِ شبکه‌ی مشتری — نودهایی که از «مرورگر ادمین» (همان شبکه‌ی
  // ایران) تأیید شده‌اند (bv) اول‌اند؛ بعد تازه‌ترین تأیید سروری؛ بعد کم‌پینگ‌ترین.
  // چکر TCP سمت سرور از شبکه‌ی کلادفلر تست می‌کند و «سالم» سمت سرور ≠ وصل‌شدن از ایران.
  // ⚡ 2.3.7 ادغام: ریشه‌ی «با سهمیه‌ی >۶ همه قطع‌اند» — کاندیدهای هرگز-TCP-نشده (_fresh) و
  // نودِ یک‌بار-قطع‌شده (bad≥1) وارد استخر سهمیه نمی‌شوند (تا تأیید دوباره)؛ اولویت bv ماند
  /* ⚡ 2.4.7 (گزارش کاربر: «یک کلیک، همه‌ی کانفیگ‌ها را خالی کرد»): بدِ یک‌باره (bad==1) دیگر
     استخر را نمی‌تراشد — «مشکوک» است: در ساب می‌ماند ولی آخرِ اولویت؛ حذف از استخر = بدِ
     دوم (bad>=2) که همان آستانه‌ی حذف قطعی است. کاندیدِ هرگز-تأییدنشده (_fresh) مثل قبل بیرون. */
  return nodes
    .filter((n) => n && n.ip && !(n._fresh && !Number(n.checked)) && !(Number(n.bad) >= 2))
