/* ⚡ 2.5.3 — پوشش SNI: SNI در ClientHello = دامنه‌ی پوشش (لبه گواهیِ همان را می‌دهد و فیلتر دامنه‌ی
   پوشش را می‌بیند)؛ هدر Host = دامنه‌ی خود ورکر (مسیردهی لبه تغییری نمی‌کند). همین راز کانفیگ‌هایی
   بود که «از دامنه‌های بزرگ می‌گذشتند» بی‌آنکه به آن سرویس تعلق داشته باشند. */
