      if (m && !m[1].split(".").some((o) => Number(o) > 255) && (Number(m[2]) || 443) <= 65535) out.push({ name: "📡 پاسارگاد·" + (i + 1), addr: m[1], port: Number(m[2]) || 443, tls: isTlsPort(Number(m[2]) || 443), frag: null });
