  const links = [];
  const limV = userLimit(user); /* ⚡ ۳۰۱ (باگ ۱): سقفِ سخت روی خروجی نهایی — ویژه‌ها/آینه‌ها هم داخل سقف */
  const sni = sniFrontFor(settings, hosts[0]); /* ⚡ 2.5.3: پوشش SNI — فقط نام TLS */
