    const wsPath = buildWsPath(path, proxyIpForNode({ ip: hashIp || server, port }, settings), tagU); /* ⚡ 2.5.2: هش روی IP واقعی نود — هر کانفیگ رله‌ی خودش */
    const wsPathY = wsPath.replace(/\\/g, "\\\\").replace(/"/g, "'") /* ⚡ زره 2.4.8: گیومه‌ی داخل path قبلاً YAML clash را می‌شکست (اثبات: پارس js-yaml) — کوتاه‌به-تک‌کوت بیرونِ قالب */;
