const proxyIpCache = { at: 0, ips: [] };
async function fetchProxyIpList() {
  if (proxyIpCache.at && Date.now() - proxyIpCache.at < 600000) return proxyIpCache.ips;
  // ⚡ 2.3.4: بذر = رله‌های تأییدشده‌ی داخلی، فقط-IP (نام‌های چرخان مال موتورند؛ قرارداد این
  // فهرست «IP خام» است)؛ منابع زنده فقط مکمل
  const out = new Set(FALLBACK_PROXYIPS.filter((x) => isLikelyIp(String(x).split(":")[0])));
  // ⚡ 2.1.6: دامنه‌های چرخان cmliussss — از طریق DoH (JSON) رزولو می‌شوند؛ همیشه به ProxyIPهای
  // زنده‌ی نگهداری‌شده توسط جامعه اشاره می‌کنند (سورس قبلی ipdb.api.030101.xyz مرده بود → HTML)
  const doh = async (name) => {
    try {
      const c = new AbortController(); const t = setTimeout(() => c.abort(), 6000);
      const r = await fetch("https://cloudflare-dns.com/dns-query?name=" + encodeURIComponent(name) + "&type=A", { headers: { Accept: "application/dns-json" }, signal: c.signal, cf: { cacheTtl: 600 } });
      clearTimeout(t);
      const j = await r.json();
      for (const a of (j && j.Answer) || []) if (a.type === 1 && isLikelyIp(String(a.data))) out.add(String(a.data));
    } catch {}
  };
  await Promise.all([
    doh("proxyip.cmliussss.net"),
    doh("proxyip.us.cmliussss.net"),
    doh("proxyip.jp.cmliussss.net"),
    doh("proxyip.tr.cmliussss.net"),
    doh("proxyip.hk.cmliussss.net"),
    doh("proxyip.sg.cmliussss.net"),
    doh("proxyip.kr.cmliussss.net"),
    doh("proxyip.de.cmliussss.net"),
    doh("proxyip.in.cmliussss.net"), // ⚡ 2.3.9 (تأیید شد)
  ]);
  // لیست متنی زنده‌ی جامعه (تست‌شده) + سورس قدیمی به‌صورت احتیاطی — پارس سخت‌گیرانه
  for (const listUrl of ["https://raw.githubusercontent.com/Zakkaland/CF-ProxyIP/main/ProxyIP", "https://ipdb.api.030101.xyz/?type=proxyip"]) {
    try {
      const c2 = new AbortController(); const t2 = setTimeout(() => c2.abort(), 6000);
      const r2 = await fetch(listUrl, { signal: c2.signal, cf: { cacheTtl: 600 } });
      clearTimeout(t2);
      if (!r2.ok) continue;
      const txt2 = await r2.text();
      for (const line of txt2.split(/\r?\n/)) {
        const x = line.trim().split("#")[0].split("|")[0].trim();
        const m = x.match(/^(\d{1,3}(?:\.\d{1,3}){3})(?::(\d{2,5}))?$/);
        if (m) out.add(m[2] ? m[1] + ":" + m[2] : m[1]);
      }
    } catch {}
  }
  // ⚡ 2.3.4: چیدمان یک‌درمیان — تأییدشده‌های داخلی (فقط IP؛ نام‌های چرخان مال موتور) جفت با
  // کاندیدهای زنده‌ی جامعه → پیشنهادها هم سالم‌اند هم تازه؛ سقف ۴۸
  const bakedArr = [...new Set(FALLBACK_PROXYIPS.filter((x) => isLikelyIp(String(x).split(":")[0])))];
  const restArr = [...out].filter((x) => !bakedArr.some((b) => String(b).toLowerCase() === String(x).toLowerCase()));
  const ips = [];
  const maxLen = Math.max(bakedArr.length, restArr.length);
  for (let i = 0; i < maxLen && ips.length < 48; i++) {
    if (i < bakedArr.length) ips.push(bakedArr[i]);
    if (i < restArr.length) ips.push(restArr[i]);
  }
  if (ips.length) {
    proxyIpCache.at = Date.now();
    proxyIpCache.ips = ips;
    return ips;
  }
  return proxyIpCache.ips.length ? proxyIpCache.ips : FALLBACK_PROXYIPS.slice();
}

// ⚡ 2.1.8/2.1.9: رنج‌های شناخته‌شده‌ی پرترافیک — دیتابیس‌های geo این‌ها را کامل می‌شناسند
// (ضد-«خطای geo ip» در سایت‌های چکر) و از نظر کیفیت اتصال هم پرتست‌ترند
const PREFERRED_CF_PREFIXES = [
  "104.16.", "104.17.", "104.18.", "104.19.", "104.20.", "104.21.", "104.22.",
  "104.24.", "104.25.", "104.26.", "104.27.",
  "162.159.", "172.64.", "172.65.", "172.66.", "172.67.",
  "188.114.9", "188.114.10", "188.114.11", "141.101.",
];
/* ⚡ پچ 2.4.6: کاندیدهای IPv6 (لبه‌ی رسمی) — کاربر خواست IP6 هم با پرچم درست بیاید */
function sampleV6(max) {
  const out = new Set();
  const bases = ["2400:cb00:", "2606:4700:", "2803:f800:", "2405:b500:", "2405:8100:", "2c0f:f248:"];
  const h = () => Math.floor(Math.random() * 65536).toString(16);
  let guard = 0;
  while (out.size < max && guard++ < max * 8) out.add(bases[Math.floor(Math.random() * bases.length)] + h() + ":" + h() + ":" + h() + ":" + h());
  guard = 0;
  while (out.size < max && guard++ < max * 4) out.add("2a06:98c" + Math.floor(Math.random() * 8) + ":" + h() + ":" + h() + ":" + h());
  return [...out];
}
function samplePreferred(max) {
  const out = new Set();
  let guard = 0;
  while (out.size < max && guard++ < max * 6) {
    const p = PREFERRED_CF_PREFIXES[Math.floor(Math.random() * PREFERRED_CF_PREFIXES.length)];
    const ip = p + Math.floor(Math.random() * 256) + "." + Math.floor(Math.random() * 256);
    if (isLikelyIp(ip)) out.add(ip);
  }
  return [...out];
}

function sampleFromRanges(ranges, max) {
  const out = [];
  const seen = new Set();
  const list = ranges || [];
  for (const cidr of list) {
    if (out.length >= max) break;
    const m = String(cidr).match(/^(\d{1,3}(?:\.\d{1,3}){3})\/(\d{1,2})$/);
    if (!m) continue;
    const b = m[1].split(".").map(Number);
    const bits = Math.max(12, Math.min(24, Number(m[2])));
    const blocks = 1 << (24 - bits);
    const want = Math.min(24, Math.ceil(max / Math.max(1, list.length)));
    for (let i = 0; i < want && out.length < max; i++) {
      const blk = blocks > 1 ? Math.floor(Math.random() * blocks) : 0;
      const third = b[2] + blk;
      if (third > 255) continue;
      const ip = b[0] + "." + b[1] + "." + third + "." + (1 + Math.floor(Math.random() * 254));
      if (!seen.has(ip)) {
        seen.add(ip);
        out.push(ip);
      }
    }
  }
  return out;
}

// ⚡ 2.1.5 — خودآزمایی محیط (per-isolate، کش ۱۰ دقیقه): واقعیت‌های runtime را صریح نشان می‌دهد
let envCheckCache = null;
/* ⚡ 2.5.5-موج۱۶ (۲۳۲): «تشخیص مسیر» — سه پروبِ زمان‌دار تا «همیشه قطع» به جمله‌ی قابل‌فهم
   تبدیل شود: مقصد مستقیم (خارج-CF) / لبه‌ی CF از سرور (مسدود = طبیعی) / رله‌ی پنل */
async function probePath(host, port) {
  const t0 = Date.now();
  let sk = null;
  try {
    sk = await openTcp(host, port, 3500);
    if (!sk) return { ok: false, ms: Date.now() - t0, kind: "closed" };
    /* ⚡ ۲۶۵ (باگِ گزارشِ کاذب): به پورت‌های TLS «GET» خام می‌فرستادیم → سرورِ TLS از
       plaintext خاموش می‌شود → «silent» قلابی برای رله‌های کاملاً سالم (تجربه‌ی زنده:
       144.31.63.230 سالن گزارش می‌شد درحالی‌که تونل کامل از رویش پاس می‌شد). ورکر سوکتِ خام
       دارد نه TLS-کلاینت → برای پورت‌های ≠۸۰ تنها سیگنالِ صادقانه = TCP-open. */
    if (Number(port) !== 80) {
      const ms = Date.now() - t0;
      try { sk.close(); } catch {}
      return { ok: true, ms, kind: "tcp" };
    }
    const got = await firstByte(sk, new TextEncoder().encode("GET /cdn-cgi/trace HTTP/1.1\r\nHost: " + host + "\r\nConnection: close\r\n\r\n"), 3500);
    const ms = Date.now() - t0;
    try { sk.close(); } catch {}
    if (!got) return { ok: false, ms, kind: "silent" };
    if (tlsBogus(port, got.chunk)) return { ok: false, ms, kind: "http" };
    return { ok: true, ms, kind: (got.chunk[0] === 0x16 || got.chunk[0] === 0x15) ? "tls" : "raw" };
  } catch {
    try { if (sk) sk.close(); } catch {}
    return { ok: false, ms: Date.now() - t0, kind: "err" };
  }
}
async function envCheck(env, state) {
  if (envCheckCache && Date.now() - envCheckCache.at < 60000) return envCheckCache.res; /* ⚡ ۲۶۵: ۱۰دقیقه→۶۰ثانیه */
  const res = { at: Date.now() };
  try {
    const c = new AbortController(); const t = setTimeout(() => c.abort(), 5000);
    const r = await fetch("https://www.cloudflare.com/cdn-cgi/trace", { signal: c.signal }); /* ⚡ 2.5.4: IP خام ۱۰۰۳ می‌داد → «blocked» قلابی؛ دامنه = سیگنال واقعی */
    clearTimeout(t);
    res.ipFetch = r.ok ? "ok" : "http-" + r.status;
  } catch { res.ipFetch = "blocked"; }
  try {
    const sk = connect({ hostname: "1.1.1.1", port: 443 });
    try { sk.close(); } catch {}
    res.cfConnect = "ok";
  } catch { res.cfConnect = "blocked"; }
  try {
    const relayHost = state ? (parseProxyIPs(state.settings)[0] || FALLBACK_PROXYIPS[0]) : "";
    const parts = [];
    const p1 = await probePath("www.wikipedia.org", 443); /* مقصد مستقیم خارج-CF */
    parts.push("مقصد مستقیم: " + (p1.ok ? "✓ " + p1.ms + "ms" : "✕ (" + p1.kind + ")"));
    const p2 = await probePath(samplePreferred(1)[0] || "104.16.132.229", 443); /* لبه‌ی CF از سرور — مسدود = طبیعی */
    parts.push("لبه‌ی CF از سرور: " + (p2.ok ? "✓ " + p2.ms + "ms" : "مسدود (طبیعی است)"));
    if (relayHost) {
      const rh = String(relayHost).split(":")[0];
      const p3 = await probePath(rh, Number(String(relayHost).split(":")[1]) || 443);
      parts.push("رله‌ی پنل (" + rh + "): " + (p3.ok ? "✓ " + p3.ms + "ms" : "✕ (" + p3.kind + ")"));
    }
    res.probes = parts;
  } catch {}
  envCheckCache = { at: Date.now(), res };
  return res;
}

function dohUpstream() { return "https://dns.google/dns-query"; } /* ⚡ ۲۷۲-ب: dns.google اول (cloudflare-dns.com از ورکر 400 می‌دهد — اثبات زنده)؛ fallback دامنه‌دار در pipeUdp */
async function dohProxy(request) {
  try {
  const url = new URL(request.url);
  const target = dohUpstream() + url.search;
  const h = new Headers();
  h.set("Accept", request.headers.get("Accept") || "application/dns-message");
  if (request.method === "POST") h.set("Content-Type", "application/dns-message");
  const r = await fetch(target, { method: request.method, headers: h, body: request.method === "POST" ? request.body : undefined });
  const out = new Headers(r.headers);
  out.set("Access-Control-Allow-Origin", "*");
  return new Response(r.body, { status: r.status, headers: out });
  } catch {
    // ⚡ 2.1.2: حتی DoH هم استثنا نمی‌پراند
    return json({ ok: false, error: "DoH موقتاً در دسترس نیست" }, 502);
  }
}

function nginxPage() {
  return new Response(
    `<!DOCTYPE html><html><head><title>Welcome to nginx!</title><style>body{width:35em;margin:0 auto;font-family:Tahoma,Verdana,Arial,sans-serif}</style></head><body><h1>Welcome to nginx!</h1><p>If you see this page, the nginx web server is successfully installed and working. Further configuration is required.</p></body></html>`,
    { headers: { "Content-Type": "text/html;charset=utf-8" } }
  );
}

function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
    "Cache-Control": "no-store",
  };
}
function safeJson(obj) {
  return JSON.stringify(obj)
    .replace(/</g, "\\u003c")
    .replace(/>/g, "\\u003e")
    .replace(/&/g, "\\u0026")
    .replace(/\u2028/g, "\\u2028")
    .replace(/\u2029/g, "\\u2029");
}
function json(obj, status = 200, extra) {
  return new Response(JSON.stringify(obj), { status, headers: { "Content-Type": "application/json;charset=utf-8", ...corsHeaders(), ...(extra || {}) } });
}
function html(body, extra) {
  /* ⚡ ۲۹۰ (2.7.7): هدرهای امنیتیِ HTML — الگوی سخت‌سازیِ BlueKnight (نوسنایف/بدون‌فریم/بدون‌رفرر) */
  const secHeaders = { "X-Content-Type-Options": "nosniff", "X-Frame-Options": "DENY", "Referrer-Policy": "no-referrer", "Content-Security-Policy": "frame-ancestors 'none'; base-uri 'self'; form-action 'self'", ...(extra || {}) };
  return new Response(body, { headers: { "Content-Type": "text/html;charset=utf-8", "Cache-Control": "no-store", ...secHeaders } });
}

// ============ UI پاسارگاد 1.9.5 ============
function esc(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

